<?php require '../includes/functions.php';$u=require_role('citizen');verify_csrf();$pdo=db();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$password=$_POST['password']??'';if(mb_strlen($name)<2||mb_strlen($name)>140){$message='Enter a valid name.';}elseif($password!==''&&strlen($password)<10){$message='New password must be at least 10 characters.';}else{if($password!=='')$q=$pdo->prepare('UPDATE users SET full_name=?,phone=?,address=?,password_hash=? WHERE id=?');else $q=$pdo->prepare('UPDATE users SET full_name=?,phone=?,address=? WHERE id=?');$password!==''?$q->execute([$name,$phone?:null,$address?:null,password_hash($password,PASSWORD_DEFAULT),$u['id']]):$q->execute([$name,$phone?:null,$address?:null,$u['id']]);$_SESSION['user']['full_name']=$name;$message='Profile updated.';}}$q=$pdo->prepare('SELECT full_name,email,phone,address FROM users WHERE id=?');$q->execute([$u['id']]);$profile=$q->fetch();$pageTitle='Profile';require '../includes/header.php';?><section class="panel form-narrow"><h1>Profile settings</h1><?php if($message):?><p class="notice"><?=e($message)?></p><?php endif?><form method="post"><?=csrf_field()?><label>Name</label><input name="full_name" required maxlength="140" value="<?=e($profile['full_name'])?>"><label>Email (cannot be changed here)</label><input value="<?=e($profile['email'])?>" disabled><label>Phone</label><input name="phone" maxlength="30" value="<?=e($profile['phone'])?>"><label>Address</label><input name="address" maxlength="255" value="<?=e($profile['address'])?>"><label>New password (leave blank to keep current password)</label><input type="password" name="password" minlength="10"><button>Save profile</button></form></section><?php require '../includes/footer.php';?>
